package stages

import (
	"context"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"strings"

	"github.com/ankitaniket/clean-me/internal/run"
	"github.com/ankitaniket/clean-me/internal/sizeutil"
	"github.com/ankitaniket/clean-me/internal/stage"
	"github.com/ankitaniket/clean-me/internal/trash"
)

// Node reclaims space from Node.js projects: node_modules directories (removed
// trash-first, regenerated by a reinstall) and the npm download cache.
type Node struct{}

func (Node) Name() string { return "node" }

func (Node) Available() bool { return true }

const nodeMaxDepth = 7

func (Node) Scan(ctx context.Context, o stage.Options) ([]stage.Item, error) {
	roots := o.Paths
	if len(roots) == 0 {
		roots = []string{"."}
	}
	var items []stage.Item
	for _, root := range roots {
		base := strings.Count(filepath.Clean(root), string(os.PathSeparator))
		_ = filepath.WalkDir(root, func(p string, d fs.DirEntry, err error) error {
			if err != nil || !d.IsDir() {
				return nil
			}
			name := d.Name()
			if name == ".git" || strings.HasPrefix(name, ".") && name != "." {
				return filepath.SkipDir
			}
			if strings.Count(filepath.Clean(p), string(os.PathSeparator))-base > nodeMaxDepth {
				return filepath.SkipDir
			}
			if name == "node_modules" {
				size, _ := sizeutil.DirSize(p)
				it := stage.Item{
					Stage:       "node",
					Path:        p,
					Purpose:     "node_modules — reinstallable with `npm/pnpm/yarn install`",
					Size:        size,
					Reclaimable: size,
					Tier:        stage.TierSafe,
				}
				if pm := linkedManager(p); pm != "" {
					it.Warn = fmt.Sprintf("%s-linked: real reclaim is lower; run `%s store prune` to free the shared store", pm, pm)
				}
				items = append(items, it)
				return filepath.SkipDir // don't descend into node_modules
			}
			return nil
		})
	}

	// npm download cache (global, re-downloadable).
	if run.Look("npm") {
		if home, err := os.UserHomeDir(); err == nil {
			cache := filepath.Join(home, ".npm", "_cacache")
			if size, _ := sizeutil.DirSize(cache); size > 0 {
				items = append(items, stage.Item{
					Stage: "node", Path: cache,
					Purpose:     "npm download cache, re-downloadable",
					Size:        size,
					Reclaimable: size,
					Tier:        stage.TierSafe,
					Command:     "npm cache clean --force",
				})
			}
		}
	}
	return items, nil
}

func (Node) Apply(ctx context.Context, items []stage.Item, o stage.Options) (stage.Result, error) {
	res := stage.Result{Stage: "node"}
	for _, it := range items {
		if !gated(it, o) {
			res.Skipped++
			continue
		}
		if it.Command != "" {
			args := strings.Fields(it.Command)
			if _, err := run.Run(ctx, o.DryRun, args[0], args[1:]...); err != nil {
				res.Errors = append(res.Errors, err)
				continue
			}
		} else if !o.DryRun {
			if _, err := trash.Remove(it.Path, o.NoTrash); err != nil {
				res.Errors = append(res.Errors, fmt.Errorf("%s: %w", it.Path, err))
				continue
			}
		}
		res.Removed++
		res.Reclaimed += it.Reclaimable
	}
	return res, nil
}

// linkedManager returns "pnpm" or "bun" when a node_modules is populated via a
// shared store/hard-links, where folder size overstates reclaimable bytes.
func linkedManager(nodeModules string) string {
	if sizeutil.Exists(filepath.Join(nodeModules, ".pnpm")) {
		return "pnpm"
	}
	if sizeutil.Exists(filepath.Join(nodeModules, ".bun")) || sizeutil.Exists(filepath.Join(nodeModules, ".cache", ".bun")) {
		return "bun"
	}
	return ""
}
